-- Reference SQL for migration 0013; Go owns safe legacy-column repair.
CREATE TABLE IF NOT EXISTS spy_rooms (id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL DEFAULT '', host_user_id INTEGER NOT NULL, club_id INTEGER, country TEXT NOT NULL DEFAULT 'china', cap INTEGER NOT NULL DEFAULT 8, joined INTEGER NOT NULL DEFAULT 0, dist_civilian INTEGER NOT NULL DEFAULT 0, dist_spy INTEGER NOT NULL DEFAULT 0, dist_blank INTEGER NOT NULL DEFAULT 0, phase TEXT NOT NULL DEFAULT 'lobby', round INTEGER NOT NULL DEFAULT 1, timer_profile TEXT NOT NULL DEFAULT 'standard', deadline_at INTEGER NOT NULL DEFAULT 0, speaker_seat INTEGER NOT NULL DEFAULT 0, vote_sealed_at INTEGER NOT NULL DEFAULT 0, revote_used INTEGER NOT NULL DEFAULT 0, spectate INTEGER NOT NULL DEFAULT 1, spectate_delay INTEGER NOT NULL DEFAULT 60, need_code INTEGER NOT NULL DEFAULT 0, join_code TEXT NOT NULL DEFAULT '', word_a TEXT NOT NULL DEFAULT '', word_b TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'waiting', winner TEXT NOT NULL DEFAULT '', host_last_seen_at INTEGER NOT NULL DEFAULT 0, rev INTEGER NOT NULL DEFAULT 1, last_activity_at INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS spy_seats (id INTEGER PRIMARY KEY AUTOINCREMENT, room_id INTEGER NOT NULL, seat INTEGER NOT NULL, user_id INTEGER, nick TEXT NOT NULL DEFAULT '', avatar TEXT NOT NULL DEFAULT '', role TEXT NOT NULL DEFAULT '', role_preset TEXT NOT NULL DEFAULT '', ready_at INTEGER NOT NULL DEFAULT 0, viewed_at INTEGER NOT NULL DEFAULT 0, out_round INTEGER, out_by TEXT NOT NULL DEFAULT '', last_seen_at INTEGER NOT NULL DEFAULT 0, joined_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(room_id,seat), UNIQUE(room_id,user_id));
CREATE TABLE IF NOT EXISTS spy_words (room_id INTEGER NOT NULL PRIMARY KEY, pair_id INTEGER NOT NULL DEFAULT 0, civilian_word TEXT NOT NULL DEFAULT '', spy_word TEXT NOT NULL DEFAULT '', difficulty TEXT NOT NULL DEFAULT 'mid', similarity TEXT NOT NULL DEFAULT 'near', dealt_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS spy_word_pairs (id INTEGER PRIMARY KEY AUTOINCREMENT, a TEXT NOT NULL, b TEXT NOT NULL, level TEXT NOT NULL DEFAULT 'mid', similarity TEXT NOT NULL DEFAULT 'near', used_count INTEGER NOT NULL DEFAULT 0, enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(a,b));
CREATE TABLE IF NOT EXISTS spy_sentences (id INTEGER PRIMARY KEY AUTOINCREMENT, room_id INTEGER NOT NULL, round INTEGER NOT NULL, seat INTEGER NOT NULL, body TEXT NOT NULL, skipped INTEGER NOT NULL DEFAULT 0, submitted_at INTEGER NOT NULL DEFAULT 0, UNIQUE(room_id,round,seat));
CREATE TABLE IF NOT EXISTS spy_votes (id INTEGER PRIMARY KEY AUTOINCREMENT, room_id INTEGER NOT NULL, round INTEGER NOT NULL, from_seat INTEGER NOT NULL, to_seat INTEGER, sealed INTEGER NOT NULL DEFAULT 0, submitted_at INTEGER NOT NULL DEFAULT 0, UNIQUE(room_id,round,from_seat));
CREATE TABLE IF NOT EXISTS spy_night_actions (id INTEGER PRIMARY KEY AUTOINCREMENT, room_id INTEGER NOT NULL, round INTEGER NOT NULL, from_seat INTEGER NOT NULL, target_seat INTEGER, submitted_at INTEGER NOT NULL DEFAULT 0, UNIQUE(room_id,round,from_seat));
CREATE TABLE IF NOT EXISTS spy_blank_guesses (id INTEGER PRIMARY KEY AUTOINCREMENT, room_id INTEGER NOT NULL, round INTEGER NOT NULL, seat INTEGER NOT NULL, guess_a TEXT NOT NULL DEFAULT '', guess_b TEXT NOT NULL DEFAULT '', hit_a INTEGER NOT NULL DEFAULT 0, hit_b INTEGER NOT NULL DEFAULT 0, result TEXT NOT NULL DEFAULT '', host_confirmed INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL DEFAULT 0, UNIQUE(room_id,seat));
CREATE TABLE IF NOT EXISTS spy_round_outcomes (id INTEGER PRIMARY KEY AUTOINCREMENT, room_id INTEGER NOT NULL, round INTEGER NOT NULL, stage TEXT NOT NULL, eliminated_seat INTEGER, eliminated_role TEXT NOT NULL DEFAULT '', out_by TEXT NOT NULL DEFAULT '', tie INTEGER NOT NULL DEFAULT 0, host_ruling TEXT NOT NULL DEFAULT '', tally TEXT, created_at INTEGER NOT NULL DEFAULT 0, UNIQUE(room_id,round,stage));
CREATE TABLE IF NOT EXISTS spy_events (id INTEGER PRIMARY KEY AUTOINCREMENT, room_id INTEGER NOT NULL, rev INTEGER NOT NULL, kind TEXT NOT NULL, payload TEXT, created_at INTEGER NOT NULL DEFAULT 0, UNIQUE(room_id,rev));
CREATE TABLE IF NOT EXISTS spy_results (room_id INTEGER NOT NULL PRIMARY KEY, winner TEXT NOT NULL DEFAULT '', reason TEXT NOT NULL DEFAULT '', rounds INTEGER NOT NULL DEFAULT 0, awards TEXT, reveal TEXT, settled_at INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS spy_idempotency (id INTEGER PRIMARY KEY AUTOINCREMENT, idem_key TEXT NOT NULL UNIQUE, room_id INTEGER NOT NULL DEFAULT 0, response TEXT, created_at INTEGER NOT NULL DEFAULT 0, expires_at INTEGER NOT NULL DEFAULT 0);
